soloMapling/ArtificialPlayer/BotDialogue.text:
conversations:

  training_spot_debate:
    participants: 2
    lines:
      - {speaker: A, text: "你现在一般去哪练级？"}
      - {speaker: B, text: "我最近都在市场门口发呆，练级先欠着。"}
      - {speaker: A, text: "这也算一种修炼吧。", emote: 2}
      - {speaker: B, text: "修炼耐心，顺便等朋友上线。"}

  item_price_haggle:
    participants: 2
    lines:
      - {speaker: A, text: "你那组标飞齿轮多少钱？"}
      - {speaker: B, text: "不贵，看你诚心给。"}
      - {speaker: A, text: "这句话听起来就很贵。", emote: 5}
      - {speaker: B, text: "哈哈，那给你少一点。"}

  scroll_results:
    participants: 2
    lines:
      - {speaker: A, text: "我刚刚连续砸爆三张卷。", emote: 6}
      - {speaker: B, text: "卷轴这东西，越想成越不成。"}
      - {speaker: A, text: "我现在只想坐下冷静一分钟。"}
      - {speaker: B, text: "先别点下一张，手抖会出事。"}

  fashion_talk:
    participants: 2
    lines:
      - {speaker: A, text: "你这身点装挺好看，哪里配的？"}
      - {speaker: B, text: "在时尚点装那边随便挑的。", emote: 2}
      - {speaker: A, text: "我也想换一套，站市场比较有排面。"}
      - {speaker: B, text: "先试帽子，帽子决定气质。"}

  boss_planning:
    participants: 2
    lines:
      - {speaker: A, text: "晚上有人打扎昆吗？"}
      - {speaker: B, text: "有的话喊我，我可以补位。"}
      - {speaker: A, text: "缺主教，其他位置好像都有。"}
      - {speaker: B, text: "那我去问问公会。", emote: 2}

  market_gossip:
    participants: 2
    lines:
      - {speaker: A, text: "今天市场人看起来多了不少。"}
      - {speaker: B, text: "是啊，逛起来终于有点热闹了。"}
      - {speaker: A, text: "刚刚还看到有人一直放技能。"}
      - {speaker: B, text: "正常，站久了总得活动一下。", emote: 3}

  quest_help:
    participants: 2
    lines:
      - {speaker: A, text: "去冰峰雪域是不是要从天空之城下塔？"}
      - {speaker: B, text: "对，一路往下走，记得带药。"}
      - {speaker: A, text: "那塔也太长了吧。", emote: 7}
      - {speaker: B, text: "第一次走都这么想。"}

  afk_check:
    participants: 2
    lines:
      - {speaker: A, text: "人在吗？"}
      - {speaker: B, text: "在，刚刚倒水去了。"}
      - {speaker: A, text: "我还以为你掉线了。"}
      - {speaker: B, text: "没掉，市场太舒服了就挂机了一下。"}

  chair_chat:
    participants: 2
    lines:
      - {speaker: A, text: "这椅子看着不错。"}
      - {speaker: B, text: "坐久了还能换一个。", emote: 0}
      - {speaker: A, text: "你这是把市场当客厅了。"}
      - {speaker: B, text: "自由市场嘛，自由一点。"}

  party_waiting:
    participants: 3
    lines:
      - {speaker: A, text: "队长还没来吗？"}
      - {speaker: B, text: "说是去买药了。"}
      - {speaker: C, text: "那我再整理一下背包。"}
      - {speaker: A, text: "别又整理到半小时。", emote: 5}
      - {speaker: B, text: "放心，这次应该只要二十分钟。", emote: 2}

  guild_recruit:
    participants: 3
    lines:
      - {speaker: A, text: "你们公会还收人吗？"}
      - {speaker: B, text: "收啊，常在线就行。"}
      - {speaker: C, text: "会聊天加分。", emote: 2}
      - {speaker: A, text: "那我应该挺合格。"}

  maple_nostalgia:
    participants: 3
    lines:
      - {speaker: A, text: "以前射手村人真的很多。"}
      - {speaker: B, text: "抢频道、抢怪、抢位置。"}
      - {speaker: C, text: "还有人为了名声吵半天。", emote: 4}
      - {speaker: A, text: "现在想想还挺怀念。"}

